// Checkout conversion fix: ensure paidEvents increment on successful payment
const { db } = require('../constants/database');

module.exports = async function processCheckout(sessionId, paymentResult) {
  if (!sessionId || !paymentResult || paymentResult.status !== 'completed') {
    return { success: false, reason: 'payment not completed' };
  }
  // Increment paidEvents
  await db.collection('metrics').updateOne(
    { _id: 'revenue' },
    { $inc: { paidEvents: 1, totalRevenue: paymentResult.amount } },
    { upsert: true }
  );
  // Mark session as paid
  await db.collection('sessions').updateOne(
    { sessionId },
    { $set: { paid: true, paidAt: new Date() } }
  );
  return { success: true };
};
